import{z as n,x as A,o as B,c as o,q as s,j as r,D as l,d as i,s as t,S as E,b as a}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"910C 双 Die 共封装与片上互连","description":"","frontmatter":{"title":"910C 双 Die 共封装与片上互连","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ascend-910c-dual-die.md","filePath":"llm/ascend-910c-dual-die.md","lastUpdated":1791413859000}'),d={name:"llm/ascend-910c-dual-die.md"};function C(p,e,u,c,m,P){const D=A("Mermaid");return B(),o("div",null,[e[2]||(e[2]=s('<h1 id="_910c-双-die-共封装与片上互连" tabindex="-1">910C 双 Die 共封装与片上互连 <a class="header-anchor" href="#_910c-双-die-共封装与片上互连" aria-label="Permalink to &quot;910C 双 Die 共封装与片上互连&quot;">​</a></h1><div class="epigraph"><p>910C 是双 Die 封装：两颗相同计算 Die 共封装，共享八个封装上内存栈，并以高带宽 Die 间互连相连。</p><footer>—— Zuo et al., Serving Large Language Models on Huawei CloudMatrix384（公开论文 §3.3.1）</footer></div><p><a href="/llm/davinci-cube-vector">上一课</a>把 AI Core 写成 Cube / Vector / Scalar 三条流水，外加 MTE/FixPipe 搬运；融合的目标是让 Cube 输出留在 UB 给 Vector。缺口是单 Die 受光罩与 HBM PHY 限制，算力与内存涨到头之后怎么封装。本课写 910C <strong>双 Die 共封装</strong>：两颗裸片、8 栈 128 GB、Die 间最高 540 GB/s。不重讲 NZ 布局与哪条流水吃 GEMM。后课 CANN 图编译默认已经读完：软件看见的「一张 910C」内部是两个并行原子。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><span class="marginnote">光罩（reticle）是光刻机一次曝光能刻出的最大硅片面积上限，约 850 mm² 量级；单颗 Die 再大也不能越过这条线。想堆更多晶体管，要么换更细的工艺，要么把两颗 Die 封在一起——910C 选了后者，工艺不动、算力翻倍。</span></p><p>单 Die 受光罩面积、良率与 HBM PHY 数量限制，算力与内存涨到头。下一代可以选择更大的单 Die，或把两颗成熟 Die 封在一起。910C 走后者：软件看见的「一张 910C」内部其实是两个计算复合体，靠封装内互连当桥梁。问题是：对框架而言，910C 是 1 个装置还是 2 个 rank？KV 与专家按封装切还是按 Die 切？Die 间 270 GB/s/方向比 UB 平面与 HBM 都窄一档，放错通信就会在封装内部打满这座桥。</p><p>CloudMatrix384 把 384 张 910C 收成超节点时，表格按 <strong>per-die</strong> 报带宽，并写明每张 910C 两 Die。服务侧 EP320 把 DeepSeek-R1 的专家铺到 <strong>320 个 Die</strong>（160 张 910C），「每 Die 一个专家」——这明确把 Die 当成并行原子，而不是把封装当成不可分割的一张卡。</p><h3 id="共享八栈不等于单一统一内存" tabindex="-1">共享八栈不等于单一统一内存 <a class="header-anchor" href="#共享八栈不等于单一统一内存" aria-label="Permalink to &quot;共享八栈不等于单一统一内存&quot;">​</a></h3><p>八个 16 GB 栈提供 128 GB 封装容量，每 Die 64 GB。论文的图示是共封装共享栈，同时给出每 Die 1.6 TB/s。编程上仍应假设<strong>近端优先</strong>：算子与 KV 尽量留在本 Die 的 64 GB 视图里，跨 Die 访问走 540 GB/s 的桥，而不是当 128 GB 无代价扁平空间。这与 Jalapeño 的切片化是同一类纪律，只是切分粒度从核切片变成 Die。</p><p><span class="marginnote">INT8 被写成在 910C 上达到与原生 FP8 硬件可比较的计算效率，但论文没有声称有独立的 FP8 Tensor Core。量化方案是 INT8，验收也按 INT8 进行。不要把 MXFP4 或 NVFP4 的峰值抄到 910C。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把一张 910C 当成两个紧密耦合的 NPU Die 来切并行。张量并行若只有 2 路，可以落在同一封装的两 Die 上，All-Reduce 走封装内 270 GB/s/方向，不必出芯片。专家并行以 Die 为 rank：EP 度可以等于 Die 数。数据并行的副本以封装或节点（论文中每节点 8 张 910C）为单位，减少碎片。KV 按 Die 的 64 GB 规划，跨 Die 拼接要计入桥的带宽；长上下文更合理的是用 UB 把许多封装的内存池化，而不是在一张卡的两 Die 之间硬挤 128 GB 统一池。</p><p>节点级公开结构：8 张 910C + 4 鲲鹏 + 板上 7 个 UB 交换，12 个处理器进同一层 UB。封装内桥解决的是「一张卡内部」；节点与超节点的 UB 解决的是「卡与卡」。两者不要混用数字：540 GB/s 是 Die–Die，UB 单向 392 GB/s 量级是整卡对 Scale-Up 平面（每 Die 196 GB/s 单向）。</p>',13)),(B(),r(E,null,{default:l(()=>[t(D,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TB%0A%20%20subgraph%20PKG%5B%22910C%20%E5%B0%81%E8%A3%85%22%5D%0A%20%20%20%20D0%5B%22Die0%EF%BC%9A24%20AIC%20%2B%2048%20AIV%20%C2%B7%2064%20GB%22%5D%0A%20%20%20%20D1%5B%22Die1%EF%BC%9A24%20AIC%20%2B%2048%20AIV%20%C2%B7%2064%20GB%22%5D%0A%20%20%20%20HBM%5B%228%20%C3%97%2016%20GB%20%E5%86%85%E5%AD%98%E6%A0%88%22%5D%0A%20%20%20%20D0%20---%20%7C%22%E5%90%88%E8%AE%A1%20540%20GB%2Fs%22%7C%20D1%0A%20%20%20%20D0%20---%20HBM%0A%20%20%20%20D1%20---%20HBM%0A%20%20end%0A%20%20D0%20--%3E%7C%22UB%20%C2%B7%20RDMA%22%7C%20NET%5B%22%E8%B6%85%E8%8A%82%E7%82%B9%20%2F%20%E9%9B%86%E7%BE%A4%22%5D%0A%20%20D1%20--%3E%7C%22UB%20%C2%B7%20RDMA%22%7C%20NET%0A"})]),fallback:l(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a("h3",{id:"对-mindie-与集合通信的含义",tabindex:"-1"},[i("对 MindIE 与集合通信的含义 "),a("a",{class:"header-anchor",href:"#对-mindie-与集合通信的含义","aria-label":'Permalink to "对 MindIE 与集合通信的含义"'},"​")],-1)),e[4]||(e[4]=a("p",null,[i("HCCL 通信域应能表达 Die 拓扑，而不是只枚举「NPU 0..7」。双 Die 若被操作系统暴露为两个逻辑装置，进程绑定必须钉死成对亲和，避免 TP 组跨到另一封装的远 Die 却以为还在「同一张卡」。若暴露为一个装置，运行时也要在核函数启动时把 AIC/AIV 平均分到两 Die，并显式处理桥上的同步。以你安装的 CANN / 驱动文档为准，不要假设与 CUDA "),a("code",null,"cudaSetDevice"),i(" 一一对应。")],-1)),e[5]||(e[5]=a("p",null,"CloudMatrix-Infer 的 PD 分离与 EP320 说明：decode 实例用 160 卡 320 Die，就是把双 Die 当成可调度的 320 个专家槽。这比「160 路 EP、每卡两专家串行」更有利于延迟。方法是承认封装内部有结构，而不是对调度器隐瞒。",-1)),e[6]||(e[6]=a("h2",{id:"机制",tabindex:"-1"},[i("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[7]||(e[7]=a("p",null,"双 Die 的机制是面积与良率：两颗较小的计算 Die 比一颗翻倍面积的 Die 更好造，HBM PHY 与 UB/RDMA SerDes 可以按 Die 复制。代价是 Die 间一致性与带宽。540 GB/s 合计大约是每 Die HBM 1.6 TB/s 的三分之一量级，因此跨 Die 的每次同步都比本 Die 内搬运贵。适合放在桥上的是低频、整块的激活或梯度；不适合的是 decode 每层两次、体积只有 \\(b\\times d\\) 的 All-Reduce——那应当尽量留在本 Die，或把 TP 度降下来。",-1)),(B(),r(E,null,{default:l(()=>[t(D,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E8%BF%99%E6%9D%A1%E9%80%9A%E4%BF%A1%E8%AF%A5%E8%90%BD%E5%9C%A8%E5%93%AA%E5%BA%A7%E6%A1%A5%EF%BC%9F%22%5D%0A%20%20Q%20--%3E%7C%22Die%20%E5%86%85%E7%AE%97%E5%AD%90%E9%97%B4%E6%95%B0%E6%8D%AE%22%7C%20L0%5B%22%E7%95%99%E5%9C%A8%E6%9C%AC%20Die%EF%BC%9AUB%20%2F%2064%20GB%20%E8%BF%91%E7%AB%AF%E5%86%85%E5%AD%98%22%5D%0A%20%20Q%20--%3E%7C%22%E4%BD%8E%E9%A2%91%E3%80%81%E6%95%B4%E5%9D%97%E6%BF%80%E6%B4%BB%E6%88%96%E6%A2%AF%E5%BA%A6%22%7C%20L1%5B%22%E5%B0%81%E8%A3%85%E5%86%85%E6%A1%A5%EF%BC%9A270%20GB%2Fs%20%E6%AF%8F%E6%96%B9%E5%90%91%22%5D%0A%20%20Q%20--%3E%7C%22%E8%B7%A8%E5%8D%A1%20TP%20%2F%20EP%20%E4%B8%93%E5%AE%B6%E8%B7%AF%E7%94%B1%22%7C%20L2%5B%22%E8%8A%82%E7%82%B9%20UB%EF%BC%9A%E6%AF%8F%20Die%20196%20GB%2Fs%20%E5%8D%95%E5%90%91%22%5D%0A%20%20Q%20--%3E%7C%22%E8%B7%A8%E8%8A%82%E7%82%B9%20%2F%20%E8%BF%9C%E7%AB%AF%20KV%20%E6%B1%A0%E5%8C%96%22%7C%20L3%5B%22RDMA%20Scale-Out%22%5D%0A%20%20L0%20--%3E%20W%5B%22%E6%AF%8F%E5%AD%97%E8%8A%82%E6%88%90%E6%9C%AC%EF%BC%9ADie%20%E5%86%85%20%5Clt%20%E6%A1%A5%20%5Clt%20UB%20%5Clt%20%E5%87%BA%E6%9C%BA%E6%9F%9C%22%5D%0A%20%20L1%20--%3E%20W%0A%20%20L2%20--%3E%20W%0A%20%20L3%20--%3E%20W%0A"})]),fallback:l(()=>[...e[1]||(e[1]=[i(" Loading... ",-1)])]),_:1})),e[8]||(e[8]=s('<p><span class="marginnote">数字实例：decode 时 TP=2 的 All-Reduce 每层两次，张量只有 \\(b\\times d\\)。取 \\(b=8\\)、\\(d=4096\\)、FP16，一次就是 \\(8\\times 4096\\times 2=64\\) KB——数据量很小，却要排队过桥、等两 Die 同步，延迟成本远高于字节数。这就是「窄 TP 留在本 Die」背后的算术。</span></p><p>热与供电按封装：两 Die 加八栈，散热是共封装问题。节点 8 卡已经是高密度；超节点再靠液冷与通信柜。故障上，一 Die 失效是否整封装报废，公开论文未写现场策略；运维上应按封装替换，不要假设可热摘单 Die。</p><p><span class="marginnote">论文还给出每 Die 七条 224 Gb/s 的 UB 收发。那是 Scale-Up 平面的注入，不是 Die–Die 桥。把 224 Gb/s × 7 换算成约 196 GB/s 单向，与封装内 270 GB/s/方向是两个不同的物理通道。</span></p><h3 id="与-jalapeno-双域、与-nvl-超芯的对比" tabindex="-1">与 Jalapeño 双域、与 NVL 超芯的对比 <a class="header-anchor" href="#与-jalapeno-双域、与-nvl-超芯的对比" aria-label="Permalink to &quot;与 Jalapeño 双域、与 NVL 超芯的对比&quot;">​</a></h3><p><span class="marginnote">初学者容易以为「双 Die 封装 = 一张更大的卡、128 GB 随手可用」。实际上更像是两居室共用的墙：各屋 64 GB 随便用，穿墙要走 540 GB/s 的门洞且限流，出门（UB 超节点）又是另一套门禁。放数据前先想清楚它住哪间屋。</span></p><p>Jalapeño 用以太域把 128/2048 颗整芯片连起来；910C 先在封装内用专用桥把两 Die 连起来，再在超节点用 UB。NVIDIA 超芯是 CPU–GPU 一致性互连。三者都是「把多个硅片收成一个产品」，但 910C 的两 Die 是同构计算对，不是 CPU+GPU。不要把 540 GB/s 写成 NVLink 5 的 1.8 TB/s，也不要写成 Jalapeño 本地域的 600 GB/s——数字来源不同、层级不同。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要用媒体未标注来源的 910C 算力峰值替代论文里的结构描述；本篇故意不填一份未在该论文给出的 PFLOPS 表。不要假设 128 GB 可以当单指针空间给任意算子 gather。不要在 Die 间做细粒度原子——公开材料没有提供 GPU 式的封装内统一缓存协议细节。出口管制后的工艺与产能属于商业与合规，不是这篇互连笔记的规格来源。</p><p>对 LLM 服务：优先「宽 EP、以 Die 为 rank、窄 TP」。对训练：两 Die 可以当 2 路 TP 的近端对，更大的 TP 走出 UB。始终先画通信落在哪一座桥上。</p><p><span class="marginnote">出处：Zuo et al. CloudMatrix384 论文 §3.3.1–3.3.2（双 Die、8×16 GB、3.2 TB/s、540 GB/s、24+48 核、UB/RDMA）；StrataCL 等后续公开论文对 910C 核结构的转述。不编造未公布的 Die 间协议与良率。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>910C：两颗同构计算 Die 共封装，8 栈 × 16 GB = 128 GB，封装带宽最高 3.2 TB/s。</li><li>Die 间最高 540 GB/s 合计（270 GB/s/方向），窄于本 Die HBM，跨 Die 通信要省着放。</li><li>每 Die 24 AIC + 48 AIV；并行原子常常是 Die 而不是封装。</li><li>每 Die 同时接 UB Scale-Up 与 RDMA Scale-Out，与封装内桥是不同平面。</li><li>调度与 HCCL 域必须表达双 Die 拓扑。</li><li>出处：CloudMatrix384 公开论文的 910C 结构节。</li></ul>',12))])}const h=n(d,[["render",C]]);export{F as __pageData,h as default};
